## P3 — `realpath`-Dedupe parallel auflösen

```diff
--- a/packages/coding-agent/src/session/session-listing.ts
+++ b/packages/coding-agent/src/session/session-listing.ts
@@ async function dedupeRealPaths(files: readonly string[]): Promise<string[]> {
-	const seen = new Set<string>();
-	const out: string[] = [];
-	for (const file of files) {
-		let key: string;
-		try {
-			key = await fs.promises.realpath(file);
-		} catch {
-			key = path.resolve(file);
-		}
-		if (seen.has(key)) continue;
-		seen.add(key);
-		out.push(file);
-	}
-	return out;
+	// Resolve concurrently, then dedupe in input order so the first-listed alias still wins.
+	const keys = await Promise.all(
+		files.map(async file => {
+			try {
+				return await fs.promises.realpath(file);
+			} catch {
+				return path.resolve(file);
+			}
+		}),
+	);
+	const seen = new Set<string>();
+	return files.filter((_file, index) => {
+		const key = keys[index]!;
+		if (seen.has(key)) return false;
+		seen.add(key);
+		return true;
+	});
 }
```

Warum unbegrenztes `Promise.all` statt eines Pools: `newestSessionFiles` in derselben Datei (`:850`) nutzt dasselbe Muster bereits für `stat` über alle Dateien. Die tatsächliche I/O-Parallelität begrenzt ohnehin der Threadpool. Ein Pool wäre hier eine zweite Konvention, und der Helper dafür liegt in `task/parallel.ts`, also in einem anderen Modul.

Wo die Änderung landen sollte:

- Die Funktion gehört Upstream und ist dort noch seriell (`upstream/main` `61bc6d217e`).
- Ich empfehle, sie als upstreamfähigen PR vorzubereiten; die Veröffentlichung braucht deine ausdrückliche Freigabe.
- Willst du die Ersparnis von etwa 150 ms schon vorher, kann sie als minimales Fork-Delta unter `MOMP-CONVERSATION-SEARCH` mitlaufen. Dann braucht das Inventar eine Owner-Zeile für `dedupeRealPaths`.

## Verifikation nach Anwendung

- **P1:**
  - In `packages/tui`: `bun test test/transcript-container.test.ts test/transcript-committed-release.test.ts`. Beide neuen Tests müssen vor dem Fix rot und danach grün sein.
  - Danach `bun check` und einen echten tmux-Resize-Burst in einer langen Session. Termius/iOS bleibt als Grenze offen.
- **P3:**
  - In `packages/coding-agent`: `bun test test/conversation-search.test.ts`.
  - Discovery im All-Scope vorher und nachher messen, heute 168–193 ms.
  - Liste und Reihenfolge der Pfade mit Symlink-Duplikaten vergleichen.

• **Q1** — Soll ich P1 und P3 jetzt anwenden und committen?
• **Q2** — Soll P3 als Fork-Delta mitlaufen oder nur upstream eingereicht werden?
• **Q3** — Soll ich vor der Anwendung den Resize-Burst mit realen Markdown-Blöcken messen?
• **Q4** — Soll ich für P3 einen Entwurf für Upstream-Issue und PR im Contribution-Ledger anlegen?
• **Q5** — Soll der Runtime-Audit künftig Renders pro Resize-Frame bei wachsender History mitprotokollieren?

Hier ist der Vorschlag für Hebel 1. Er ändert nur `visitEntriesFromFileStream` in `packages/coding-agent/src/session/session-loader.ts`, einer Upstream-Datei. Die Bytes werden weiter gepuffert wie bisher; neu ist nur, dass jeder Block vollständiger Zeilen einmal zu Text dekodiert und dann als String geparst wird. Angewendet habe ich nichts.

```diff
--- a/packages/coding-agent/src/session/session-loader.ts
+++ b/packages/coding-agent/src/session/session-loader.ts
@@ export async function visitEntriesFromFileStream(
 	const maxBytes = Math.max(0, options.maxBytes ?? Number.POSITIVE_INFINITY);
-	// Bytes, not text: a multibyte UTF-8 sequence straddling a chunk boundary
-	// stays intact, and Bun.JSONL.parseChunk takes typed arrays directly. Only
-	// the unconsumed remainder is held (≤ one record + a chunk), so the ≥8MiB
-	// memory guard holds — the file is never fully loaded.
+	// Buffer bytes, parse text: a multibyte UTF-8 sequence straddling a chunk
+	// boundary stays intact because only newline-terminated bytes are decoded.
+	// Bun.JSONL.parseChunk is ~2.4x slower on typed arrays than on strings
+	// (Bun 1.4.3, 640 MiB of session JSONL), so each drained batch is decoded
+	// once. Only the unconsumed remainder is held (≤ one record + a chunk, plus
+	// that batch's transient decoded copy), so the file is never fully loaded.
 	const sink = new ConcatSink();
 	const decoder = new TextDecoder();
@@
-	const hasPayload = (bytes: Uint8Array, start: number, end: number): boolean => {
+	const hasPayload = (text: string, start: number, end: number): boolean => {
 		for (let index = start; index < end; index++) {
-			const byte = bytes[index];
-			if (byte !== 0x09 && byte !== 0x0a && byte !== 0x0d && byte !== 0x20) return true;
+			const code = text.charCodeAt(index);
+			if (code !== 0x09 && code !== 0x0a && code !== 0x0d && code !== 0x20) return true;
 		}
 		return false;
 	};

 	const drain = async (endOfInput = false): Promise<void> => {
 		const view = sink.flush();
 		if (!view) return;
 		// Only newline-terminated bytes may reach the parser: a trailing fragment
 		// in the same call turns an end-of-input `done` into a syntax error at the
 		// preceding newline, which would then be miscounted as a malformed record.
 		const lastNewline = view.lastIndexOf(0x0a);
 		if (lastNewline === -1) return;
-		let buffer: Uint8Array = view.subarray(0, lastNewline + 1);
-		let consumed = 0;
-		const advance = (count: number): void => {
-			consumed += count;
-			buffer = buffer.subarray(count);
-		};
-		while (buffer.length > 0 && !stopped) {
+		const batchBytes = lastNewline + 1;
+		const text = decoder.decode(view.subarray(0, batchBytes));
+		// parseChunk reports absolute UTF-16 positions within `text`.
+		let offset = 0;
+		while (offset < text.length && !stopped) {
 			if (recordsSeen >= maxRecords) {
 				stopped = true;
 				break;
 			}
-			const { values, error, read, done } = Bun.JSONL.parseChunk(buffer);
+			const { values, error, read, done } = Bun.JSONL.parseChunk(text, offset, text.length);
 			for (const value of values) {
@@
 			if (stopped) break;
 			if (error) {
 				// Malformed record: skip past the next newline and continue.
-				const nextNewline = buffer.indexOf(0x0a, read);
+				const nextNewline = text.indexOf("\n", read);
 				if (nextNewline === -1) break; // rest of the bad line not yet received
-				if (hasPayload(buffer, read, nextNewline)) options.onMalformedRecord?.();
+				if (hasPayload(text, read, nextNewline)) options.onMalformedRecord?.();
 				recordsSeen++;
-				advance(nextNewline + 1);
+				offset = nextNewline + 1;
 				if (recordsSeen >= maxRecords) {
 					stopped = true;
 					break;
 				}
 				continue;
 			}
-			if (read === 0) {
+			if (read <= offset) {
 				// Incomplete value awaiting more bytes. Once the input has ended nothing more
 				// is coming, so it is a truncated record (parseJsonlLenient counts it too).
 				if (endOfInput) {
-					if (hasPayload(buffer, 0, buffer.length)) options.onMalformedRecord?.();
+					if (hasPayload(text, offset, text.length)) options.onMalformedRecord?.();
 					recordsSeen++;
-					advance(buffer.length);
+					offset = text.length;
 				}
 				break;
 			}
-			advance(read);
+			offset = read;
 			if (done) {
-				advance(buffer.length);
+				offset = text.length;
 				break;
 			}
 		}
-		sink.consume(consumed);
+		// Unparsed text is an unfinished value whose bytes wait for the next chunk;
+		// only that rare remainder needs re-encoding to find its byte length.
+		sink.consume(offset >= text.length ? batchBytes : batchBytes - Buffer.byteLength(text.slice(offset)));
 	};
```

```diff
--- a/packages/coding-agent/CHANGELOG.md
+++ b/packages/coding-agent/CHANGELOG.md
@@ ## [Unreleased]
 ### Changed
+- Sped up conversation search and loading of large sessions by parsing session journals as decoded text
```

## Warum das Ergebnis gleich bleibt

- **Offsets:** `parseChunk(string, start, end)` gibt absolute Positionen zurück, das habe ich geprüft. Statt Bytes wegzuschneiden, wird deshalb nur `offset` weitergesetzt.
- **UTF-8:** Wie beim bestehenden Dekodieren der Titelzeile wird nur Text bis zum letzten Zeilenumbruch dekodiert. Deshalb wird kein Mehrbyte-Zeichen zerschnitten.
- **Unfertige Werte, die über Zeilen gehen**, behalten ihre Bytes im Puffer. Die Byte-Länge muss dafür nur im seltenen Rest-Fall neu berechnet werden, also ohne zusätzlichen Aufwand im Normalfall.
- **Unverändert bleiben:** die Zählung kaputter Einträge, `maxRecords`, `maxBytes`, das Ablösen der Titelzeile und die Pausen für die Event-Loop.
- **Kosten:** Für jeden Block existiert kurzzeitig eine dekodierte Kopie, bei Nicht-Latin-1-Text bis etwa zur doppelten Größe des Blocks.

## Nachweis nach dem Anwenden

- `bun test test/session-loader-stream.test.ts`: Die Datei deckt schon ab, was zählt, zum Beispiel Mehrbyte-Zeichen über Chunk-Grenzen, kaputte Einträge über Chunks, Werte über mehrere Zeilen, `maxBytes`, `maxRecords` und abgeschnittene Enden. Ein neuer Test ist nicht nötig, weil sich am Verhalten nichts ändert.
- `bun test test/conversation-search.test.ts test/conversation-search-benchmark.test.ts`
- `bun run bench:conversation-search -- --cwd <workspace>` vorher und nachher. In meiner Probe sank der Lesepfad von 1,9 s auf 1,28 s.

## Wo das hingehört

Ich empfehle, das als Upstream-Beitrag zu behandeln und nicht als Fork-Patch. Die Datei gehört upstream, und das Fork-Inventar hat keinen Vertrag, der eine Abweichung hier rechtfertigt. Laut den Fork-Regeln wäre der Weg: einen Eintrag im Issue-Ledger anlegen (`ISSUE-NNN`, Status `Investigating`) und danach mit deiner Freigabe einen kleinen Pull Request gegen `upstream/main` stellen.

• **Q1** — Soll ich den Diff lokal anwenden und die Tests laufen lassen?
• **Q2** — Soll ich dafür einen Eintrag im Issue-Ledger mit den Messwerten anlegen?
• **Q3** — Soll ich zusätzlich den Diff für den Nachrichten-Cache pro Datei (Hebel 2) vorschlagen?
• **Q4** — Soll ich messen, wie viel schneller das Resume großer Sessions durch diesen Diff wird?
• **Q5** — Soll ich den Pull-Request-Text für upstream mit Messwerten und Testnachweis als Entwurf vorbereiten?

Das sind nur Vorschläge, angewendet wurde nichts. Gegenüber dem Selbstreview ändern sich drei Punkte, die ich beim erneuten Lesen des Codes gefunden habe:

- **E1 hat jetzt eine kleinere Strategie.** Die Validierung wandert nicht aus den Oberflächen heraus. Stattdessen sichert die Session ihre eigene Invariante an allen ihren Commit-Punkten. Dafür gibt es zwei Gründe:
  - `setSlashCommands`, das Interface `AvailableCommandsSession` und deren Tests gehören Upstream (`git grep upstream/main`). Ein Umbau würde Upstream-Dateien und Tests ändern.
  - Beim alten Vorschlag konnte ein Commit halb durchlaufen: neue Datei-Commands gesetzt, Routinen aber abgelehnt.
- **Neuer Teilbefund zu E1:** `refreshSkillsAndCommands` (`agent-session.ts:6730`) lädt Datei-Commands neu, ohne die Routinen erneut zu prüfen. Das ist ein zweiter ungeprüfter Commit-Punkt.
- **E3:** Das Risiko „Golden-Test bricht“ war falsch. Kein Test prüft die Omitted-Zeile; eine Suche nach `increase limit|Omitted` in `test/` fand keinen Treffer.

## E1 — Session prüft Routinen an allen eigenen Commit-Punkten

Eine Routine, deren Name schon ein Datei- oder Custom-Command trägt, wird künftig abgelehnt. Das gilt jetzt auch im SDK- und Print-Pfad und beim Reload. Die Prüfungen in TUI und ACP/RPC bleiben unverändert, weil sie zusätzlich Builtins und Aliase der jeweiligen Oberfläche abdecken. Die Prüfung der Session nutzt eine Teilmenge der Namen, die die Oberflächen prüfen. Was eine Oberfläche akzeptiert hat, scheitert deshalb nicht nachträglich in der Session.

```diff
--- a/packages/coding-agent/src/session/agent-session.ts
+++ b/packages/coding-agent/src/session/agent-session.ts
@@ -170,4 +170,5 @@
 	type RoutineProgress,
+	validateRoutineCommandNames,
 } from "../extensibility/routines";
@@ -1951,5 +1952,9 @@
 		this.#getEvalPreludes = config.getEvalPreludes;
 		this.#reconcileBrowserMcpFilter = config.reconcileBrowserMcpFilter;
 		this.#customCommands = config.customCommands ?? [];
+		// SDK and print sessions never run the transport advertisement checks, and routines
+		// dispatch before file-command expansion, so an unchecked collision would silently
+		// shadow the file command.
+		this.#assertRoutineCatalog(this.#slashCommands, this.#routines);
 		const recoveryHost: TurnRecoveryHost = {
@@ -6727,10 +6732,13 @@
 			.then(async () => {
 				resetCapabilities();
-				this.#slashCommands = await loadSlashCommands({
+				const slashCommands = await loadSlashCommands({
 					cwd: this.sessionManager.getCwd(),
 					extensionRoots: this.effectiveExtensionRoots,
 				});
+				// Reject before committing so a reloaded file command never hides behind a routine.
+				this.#assertRoutineCatalog(slashCommands, this.#routines);
+				this.#slashCommands = slashCommands;
 				// Resets the capability cache again, rediscovers skills, rebuilds the prompt,
@@ -7344,5 +7352,19 @@
 	setRoutines(routines: Routine[]): void {
+		this.#assertRoutineCatalog(this.#slashCommands, routines);
 		this.#routines = [...routines];
 	}
+
+	/**
+	 * Rejects duplicate routine names and names owned by session commands.
+	 * Transports add their own builtin and alias names before calling the session;
+	 * this check covers every path, including sessions that never advertise commands.
+	 */
+	#assertRoutineCatalog(slashCommands: readonly FileSlashCommand[], routines: readonly Routine[]): void {
+		const reservedNames = new Set<string>();
+		for (const command of slashCommands) reservedNames.add(command.name);
+		for (const command of this.customCommands) reservedNames.add(command.command.name);
+		validateRoutineCommandNames(routines, reservedNames);
+	}
```

Der Regressionstest ist zulässig, weil er den SDK-Defekt reproduziert. Ohne die Änderung wird die Session gebaut, und `/review-all` führt die Routine statt des Datei-Commands aus.

